 fd=os.open(str(root/n),os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o400)
 with os.fdopen(fd,'wb') as f:f.write(base64.b64decode(b64));f.flush();os.fsync(f.fileno())
